import {T,createStage,createBook,createGlobe,createCard,clamp,smooth,mix} from './spatial.js';
const mount=document.getElementById('hero3d'),stage=createStage(mount);if(!stage){mount.innerHTML='<figure class="spatial-poster"><img src="./saudi-landscape.webp" alt="A Saudi-inspired courtyard opening onto a landscape of discovery"><figcaption>Rooted in Saudi Arabia. Open to the world.</figcaption></figure>';mount.parentElement.classList.add('static-scene');mount.removeAttribute('tabindex');mount.setAttribute('aria-label','Saudi-inspired learning landscape')}else{
const {scene,camera,ground}=stage,root=new T.Group();scene.add(root);ground.position.y=-1.36;const book=createBook();book.root.position.set(0,-1.0,.25);book.root.rotation.x=.14;root.add(book.root);const globe=createGlobe(.87);root.add(globe.root);const heritage=createCard('Places that shape us.','heritage',1.48,1.04),science=createCard('Ideas come alive.','science',1.4,.98);root.add(heritage,science);
let targetYaw=-.08,targetPitch=0,yaw=-.08,pitch=0,scroll=0,progress=0,dragging=false,lastX=0,lastY=0,manual=0,pageTime=-1,auto=true,earthAngle=-2.35;
function updateScroll(){const section=document.querySelector('.hero'),r=section.getBoundingClientRect();const travel=innerWidth<760?r.height*.8:Math.max(1,r.height-innerHeight);scroll=clamp(-r.top/travel,0,1)}addEventListener('scroll',updateScroll,{passive:true});addEventListener('resize',updateScroll);updateScroll();
mount.addEventListener('pointerdown',e=>{if(e.button&&e.button!==0)return;dragging=true;lastX=e.clientX;lastY=e.clientY;mount.setPointerCapture(e.pointerId);mount.classList.add('dragging')});mount.addEventListener('pointermove',e=>{if(dragging){targetYaw=clamp(targetYaw+(e.clientX-lastX)*.006,-.85,.85);targetPitch=clamp(targetPitch+(e.clientY-lastY)*.003,-.16,.28);lastX=e.clientX;lastY=e.clientY;manual=1}});function release(){dragging=false;mount.classList.remove('dragging')}mount.addEventListener('pointerup',release);mount.addEventListener('pointercancel',release);mount.addEventListener('lostpointercapture',release);
function reset(){targetYaw=-.08;targetPitch=0;manual=0;earthAngle=-2.35}function turn(){pageTime=0}document.getElementById('heroTurn')?.addEventListener('click',turn);document.getElementById('heroReset')?.addEventListener('click',reset);document.getElementById('heroMotion')?.addEventListener('click',e=>{auto=!auto;e.currentTarget.textContent=auto?'Pause auto-motion':'Resume auto-motion';e.currentTarget.setAttribute('aria-pressed',String(!auto))});mount.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' '].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft')targetYaw=clamp(targetYaw-.12,-.85,.85);if(e.key==='ArrowRight')targetYaw=clamp(targetYaw+.12,-.85,.85);if(e.key==='ArrowUp')targetPitch=clamp(targetPitch-.06,-.16,.28);if(e.key==='ArrowDown')targetPitch=clamp(targetPitch+.06,-.16,.28);if(e.key===' ')turn();if(e.key.toLowerCase()==='r')reset()});
stage.setDraw((dt,t,reduced)=>{progress=stage.damp(progress,reduced?0:scroll,dt,5);yaw=stage.damp(yaw,targetYaw,dt,7);pitch=stage.damp(pitch,targetPitch,dt,7);const idle=auto&&!reduced;root.rotation.set(pitch,yaw+(idle&&!manual?Math.sin(t*.23)*.025:0),0);const opened=mix(.59,1,smooth(progress,0,.38));let flip=smooth(progress,.17,.76);if(pageTime>=0){pageTime+=dt;flip=smooth(pageTime/2.1);if(pageTime>2.15)pageTime=-1}book.open(opened,flip);book.root.position.y=-1-progress*.35;book.root.rotation.y=-.02+progress*.08;
globe.root.position.set(.08,.83+progress*.54+(idle?Math.sin(t*.65)*.026:0),.12+progress*.6);globe.root.scale.setScalar(1+progress*.1);if(idle)earthAngle+=dt*.024;globe.earth.rotation.y=earthAngle;heritage.position.set(-2.02-progress*.22,.36+progress*.46,-.9+progress*.22);heritage.rotation.set(.015,.23-progress*.16,-.09);science.position.set(1.99+progress*.25,1.56-progress*.06,-1.32+progress*.54);science.rotation.set(.015,-.24+progress*.13,.085);if(idle){heritage.position.y+=Math.sin(t*.58+1)*.024;science.position.y+=Math.sin(t*.47+3)*.036}camera.fov=innerWidth<760?44:36;camera.position.set(.1*progress,3.0-progress*.35,(innerWidth<760?10.9:9.4)-progress*.55);camera.lookAt(0,.25+progress*.14,0);camera.updateProjectionMatrix();});
}
